script:
(function () {
  'use strict';

  var video = document.getElementById('cameraVideo');
  var previewWrap = document.getElementById('cameraPreviewWrap');
  var placeholder = document.getElementById('cameraPlaceholder');
  var canvas = document.getElementById('captureCanvas');
  var deviceSelect = document.getElementById('deviceSelect');
  var btnStart = document.getElementById('btnStartCamera');
  var btnStop = document.getElementById('btnStopCamera');
  var btnCapture = document.getElementById('btnCapture');
  var diagnosticPanel = document.getElementById('diagnosticPanel');
  var statOrientation = document.getElementById('statOrientation');
  var statWidth = document.getElementById('statWidth');
  var statHeight = document.getElementById('statHeight');
  var cameraFacing = document.getElementById('cameraFacing');
  var deviceType = document.getElementById('deviceType');
  var sensorOrientation = document.getElementById('sensorOrientation');
  var chkFlipH = document.getElementById('chkFlipH');
  var chkFlipV = document.getElementById('chkFlipV');
  var chkMaxRes = document.getElementById('chkMaxRes');
  var statDisplayRotation = document.getElementById('statDisplayRotation');
  var statNatural = document.getElementById('statNatural');
  var statDisplayOrientation = document.getElementById('statDisplayOrientation');
  var statStreamShape = document.getElementById('statStreamShape');
  var statMatch = document.getElementById('statMatch');
  var statSensor = document.getElementById('statSensor');
  var statJpegRotation = document.getElementById('statJpegRotation');
  var statExif = document.getElementById('statExif');
  var statPreviewView = document.getElementById('statPreviewView');
  var statPreviewTransform = document.getElementById('statPreviewTransform');
  var statResMode = document.getElementById('statResMode');
  var captureList = document.getElementById('captureList');
  var captureEmpty = document.getElementById('captureEmpty');

  var currentStream = null;
  var starting = false;
  var captures = [];
  var captureIdCounter = 0;

  function escapeHtml(s) {
    var d = document.createElement('div');
    d.textContent = String(s);
    return d.innerHTML;
  }

  function setDiagnostic(items) {
    diagnosticPanel.innerHTML = items.map(function (it) {
      var sevClass = it.sev ? ' sev-' + it.sev : '';
      return '<div class="diagnostic-item' + sevClass + '"><span class="diag-icon" aria-hidden="true">' +
        '<svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="9"/></svg>' +
        '</span><span>' + it.html + '</span></div>';
    }).join('');
  }

  function currentOrientationLabel() {
    if (screen.orientation && screen.orientation.type) return screen.orientation.type;
    if (typeof window.orientation === 'number') {
      return Math.abs(window.orientation) === 90 ? 'landscape (legacy API)' : 'portrait (legacy API)';
    }
    return window.innerWidth > window.innerHeight ? 'landscape (inferred)' : 'portrait (inferred)';
  }

  // Display rotation in degrees (0/90/180/270) from the Screen
  // Orientation API, falling back to the legacy window.orientation.
  function displayRotation() {
    var a = null;
    if (screen.orientation && typeof screen.orientation.angle === 'number') a = screen.orientation.angle;
    else if (typeof window.orientation === 'number') a = window.orientation;
    if (a === null) return null;
    return ((Math.round(a / 90) * 90) % 360 + 360) % 360;
  }

  function screenShape() {
    if (screen.orientation && screen.orientation.type) return screen.orientation.type.indexOf('portrait') === 0 ? 'portrait' : 'landscape';
    return window.innerHeight >= window.innerWidth ? 'portrait' : 'landscape';
  }

  function naturalOrientation(rot) {
    if (deviceType.value === 'phone') return 'portrait';
    if (deviceType.value === 'laptop') return 'landscape';
    var shape = screenShape();
    if (rot === 90 || rot === 270) return shape === 'portrait' ? 'landscape' : 'portrait';
    return shape;
  }

  var EXIF_FOR_ROTATION = { 0: 1, 90: 6, 180: 3, 270: 8 };

  function activeFacing() {
    var track = currentStream ? currentStream.getVideoTracks()[0] : null;
    var s = track && track.getSettings ? track.getSettings() : {};
    return s.facingMode === 'user' || s.facingMode === 'environment' ? s.facingMode : cameraFacing.value;
  }

  // Preview-only flips: a CSS transform on the <video>, never the pixels
  // captured below. Mirroring never turns a picture sideways.
  function applyFlips() {
    var parts = [];
    if (chkFlipH.checked) parts.push('scaleX(-1)');
    if (chkFlipV.checked) parts.push('scaleY(-1)');
    video.style.transform = parts.join(' ');
    statPreviewTransform.textContent = parts.length ? parts.join(' ') : 'none';
    statPreviewView.textContent = (chkFlipH.checked ? 'Mirrored' : 'Natural (as others see it)') + (chkFlipV.checked ? ', upside down' : '');
  }

  function updateOrientationMath(w, h) {
    var rot = displayRotation();
    var natural = naturalOrientation(rot || 0);
    var facing = activeFacing();
    var sensor;
    if (sensorOrientation.value === 'auto') sensor = natural === 'landscape' ? 0 : (facing === 'user' ? 270 : 90);
    else sensor = parseInt(sensorOrientation.value, 10);
    var display = screenShape();
    statDisplayRotation.textContent = rot === null ? 'Not reported' : rot + '°';
    statNatural.textContent = natural;
    statDisplayOrientation.textContent = display;
    statSensor.textContent = sensor + '° (' + (facing === 'user' ? 'front' : 'back') + ')';
    var r = rot || 0;
    var jpeg = facing === 'user' ? (sensor + r) % 360 : ((sensor - r) % 360 + 360) % 360;
    statJpegRotation.textContent = jpeg + '° clockwise';
    statExif.textContent = String(EXIF_FOR_ROTATION[jpeg]);
    if (w && h) {
      var shape = w === h ? 'square' : (h > w ? 'portrait' : 'landscape');
      statStreamShape.textContent = shape + ' (' + w + '×' + h + ')';
      statMatch.textContent = shape === 'square' ? 'n/a' : (shape === display ? 'Yes' : 'No');
    } else {
      statStreamShape.textContent = '—';
      statMatch.textContent = '—';
    }
  }

  function updateLiveReadout() {
    statOrientation.textContent = currentOrientationLabel();
    var w = 0, h = 0;
    if (currentStream) {
      var track = currentStream.getVideoTracks()[0];
      var settings = track.getSettings ? track.getSettings() : {};
      w = settings.width || video.videoWidth || 0;
      h = settings.height || video.videoHeight || 0;
      statWidth.textContent = w ? String(w) : '—';
      statHeight.textContent = h ? String(h) : '—';
      statResMode.textContent = (chkMaxRes.checked ? 'Maximum requested' : 'Browser default') + (w && h ? ' · ' + w + '×' + h : '');
    } else {
      statResMode.textContent = chkMaxRes.checked ? 'Maximum requested' : 'Browser default';
    }
    updateOrientationMath(w, h);
  }

  function renderCaptureList() {
    if (!captures.length) {
      captureList.innerHTML = '';
      captureList.appendChild(captureEmpty);
      return;
    }
    captureList.innerHTML = captures.map(function (cap) {
      return '<div class="capture-row"><span class="capture-row-meta">' + escapeHtml(cap.orientation) + ' — ' + cap.width + '×' + cap.height + '</span>' +
        '<span class="capture-row-actions"><a href="' + cap.url + '" download="orientation-test-' + cap.id + '.jpg">Download</a></span></div>';
    }).join('');
  }

  function captureCurrentOrientation() {
    if (!currentStream || !video.videoWidth) return;
    canvas.width = video.videoWidth;
    canvas.height = video.videoHeight;
    canvas.getContext('2d').drawImage(video, 0, 0);
    var url = canvas.toDataURL('image/jpeg', 0.9);
    captureIdCounter++;
    captures.unshift({ id: captureIdCounter, orientation: currentOrientationLabel(), width: video.videoWidth, height: video.videoHeight, url: url });
    if (captures.length > 6) captures.pop();
    renderCaptureList();
  }

  // Same stopStream()/describeError()/populateDeviceSelect() pattern as
  // webcam-test-online's own script (see this project's CLAUDE.md -- every
  // camera tool copies this teardown block rather than importing a shared file).
  function stopStream() {
    if (currentStream) {
      currentStream.getTracks().forEach(function (t) { t.stop(); });
      currentStream = null;
    }
    video.srcObject = null;
    previewWrap.classList.remove('is-active');
    placeholder.style.display = 'flex';
    btnStop.disabled = true;
    btnCapture.disabled = true;
    statWidth.textContent = '—';
    statHeight.textContent = '—';
    updateOrientationMath(0, 0);
  }

  function describeError(err) {
    switch (err && err.name) {
      case 'NotAllowedError':
      case 'PermissionDeniedError':
        return { sev: 'error', html: '<strong>Camera access was blocked.</strong> Allow access from your browser’s address-bar icon or site settings, then try again.' };
      case 'NotFoundError':
      case 'DevicesNotFoundError':
        return { sev: 'error', html: '<strong>No camera was detected.</strong> Connect a camera and reload this page.' };
      case 'NotReadableError':
      case 'TrackStartError':
        return { sev: 'error', html: '<strong>Your camera is already in use</strong> by another app or browser tab.' };
      case 'OverconstrainedError':
        return { sev: 'error', html: '<strong>This camera doesn’t support the requested settings.</strong> Try another camera from the list.' };
      case 'SecurityError':
        return { sev: 'error', html: '<strong>Camera access requires HTTPS.</strong>' };
      default:
        return { sev: 'error', html: '<strong>Something went wrong starting the camera.</strong> ' + escapeHtml((err && err.message) || 'Unknown error') + '.' };
    }
  }

  function populateDeviceSelect(devices, currentDeviceId) {
    var cams = devices.filter(function (d) { return d.kind === 'videoinput'; });
    deviceSelect.innerHTML = '';
    cams.forEach(function (d, i) {
      var opt = document.createElement('option');
      opt.value = d.deviceId;
      opt.textContent = d.label || ('Camera ' + (i + 1));
      if (d.deviceId === currentDeviceId) opt.selected = true;
      deviceSelect.appendChild(opt);
    });
    deviceSelect.disabled = cams.length === 0;
  }

  function startStream(deviceId) {
    if (starting) return;
    starting = true;
    stopStream();
    setDiagnostic([{ sev: '', html: 'Requesting camera access…' }]);
    btnStart.disabled = true;

    // Camera picked by facing (back = environment) unless a specific
    // device is chosen; "maximum resolution" asks for an oversized ideal
    // so the browser settles on the camera's largest mode.
    var v = deviceId ? { deviceId: { exact: deviceId } } : { facingMode: { ideal: cameraFacing.value } };
    if (chkMaxRes.checked) { v.width = { ideal: 7680 }; v.height = { ideal: 4320 }; }
    navigator.mediaDevices.getUserMedia({ video: v, audio: false })
      .then(function (stream) {
        currentStream = stream;
        video.srcObject = stream;
        placeholder.style.display = 'none';
        previewWrap.classList.add('is-active');
        return video.play().catch(function () {}).then(function () { return stream; });
      })
      .then(function (stream) {
        var track = stream.getVideoTracks()[0];
        var settings = track.getSettings ? track.getSettings() : {};
        btnStop.disabled = false;
        btnCapture.disabled = false;
        setDiagnostic([{ sev: 'ok', html: '<strong>Camera is live.</strong> Rotate your phone and click Capture to compare dimensions across orientations.' }]);
        updateLiveReadout();
        return navigator.mediaDevices.enumerateDevices().then(function (devices) {
          populateDeviceSelect(devices, settings.deviceId);
        });
      })
      .catch(function (err) { setDiagnostic([describeError(err)]); stopStream(); })
      .finally(function () { starting = false; btnStart.disabled = false; });
  }

  btnStart.addEventListener('click', function () { startStream(deviceSelect.value); });
  btnStop.addEventListener('click', function () {
    stopStream();
    setDiagnostic([{ sev: '', html: 'Camera stopped.' }]);
  });
  deviceSelect.addEventListener('change', function () { if (currentStream) startStream(deviceSelect.value); });
  btnCapture.addEventListener('click', captureCurrentOrientation);
  cameraFacing.addEventListener('change', function () {
    if (currentStream) { deviceSelect.value = ''; startStream(''); } else updateLiveReadout();
  });
  chkMaxRes.addEventListener('change', function () {
    if (currentStream) startStream(deviceSelect.value); else updateLiveReadout();
  });
  [deviceType, sensorOrientation].forEach(function (el) { el.addEventListener('change', updateLiveReadout); });
  [chkFlipH, chkFlipV].forEach(function (el) { el.addEventListener('change', applyFlips); });
  video.addEventListener('resize', updateLiveReadout);

  // Listen on screen.orientation change (with a legacy-API/inferred
  // fallback for browsers that don't support it) so the readout tracks
  // rotation live, per this tool's own spec note.
  if (screen.orientation && screen.orientation.addEventListener) {
    screen.orientation.addEventListener('change', updateLiveReadout);
  } else {
    window.addEventListener('orientationchange', updateLiveReadout);
  }
  window.addEventListener('resize', updateLiveReadout);

  window.addEventListener('pagehide', stopStream);
  document.addEventListener('visibilitychange', function () {
    if (document.visibilityState === 'hidden') stopStream();
  });

  applyFlips();
  updateLiveReadout();
  renderCaptureList();

  if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
    setDiagnostic([{ sev: 'error', html: '<strong>Your browser doesn’t support camera access.</strong>' }]);
    btnStart.disabled = true;
  }
})();
